WITH lines AS (SELECT id, plan, effective_from, currency, tier_value FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_limits) li AS tier_value) SELECT CASE WHEN tier_value >= 66 THEN 'HIGH' ELSE 'LOW' END AS tier_value_tier, ROUND(AVG(tier_value), 2) AS avg_tier_value, SUM(CASE WHEN currency = 'USD' THEN tier_value ELSE 0 END) AS usd_tier_value, COUNT(*) FILTER (WHERE plan = 'enterprise') AS enterprise_rows, ROUND(SUM(tier_value) / NULLIF(COUNT(CASE WHEN plan = 'pro' THEN 1 END), 0), 2) AS tier_value_per_pro, COUNT(*) FILTER (WHERE currency = 'EUR') AS eur_rows, PERCENTILE_APPROX(tier_value, ARRAY(0.25, 0.5, 0.75)) AS tier_value_quartiles FROM lines GROUP BY tier_value_tier
